add_filter( 'woocommerce_registration_redirect', 'perfectpixel_registration_redirect', 20 );

function perfectpixel_registration_redirect( $url ) {
	$target = trim( '{{registration_redirect_url}}' );
	if ( '' === $target ) {
		return $url;
	}
	return wp_validate_redirect( 0 === strpos( $target, '/' ) ? home_url( $target ) : $target, $url );
}
